// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const subreddits = ['psychology','todayilearned','interestingasfuck','Showerthoughts','explainlikeimfive','LifeProTips'];
const hooks = [
  "Psychology says if you can't stop thinking about someone...",
  "Your brain is lying to you right now.",
  "People who do THIS are secretly genius.",
  "If someone does this, they secretly like you.",
  "The dark truth about your personality.",
  "Scientists can't explain why this happens.",
  "Only 2% of people know this about their brain.",
  "If you wake up between 3 and 5 AM...",
  "Your subconscious is trying to tell you something.",
  "The thing nobody tells you about intelligence.",
  "This psychological trick works on everyone.",
  "People who talk to themselves are actually...",
  "Your dreams are trying to warn you.",
  "The real reason you feel tired all the time.",
  "What your handwriting says about your personality."
];
const musicUrls = [
  "https://files.freemusicarchive.org/storage-freemusicarchive-org/music/no_curator/Kai_Engel/Satin/Kai_Engel_-_07_-_Satin.mp3",
  "https://files.freemusicarchive.org/storage-freemusicarchive-org/music/ccCommunity/Chad_Crouch/Arps/Chad_Crouch_-_Shipping_Lanes.mp3",
  "https://files.freemusicarchive.org/storage-freemusicarchive-org/music/WFMU/Broke_For_Free/Directionless_EP/Broke_For_Free_-_01_-_Night_Owl.mp3"
];
const seed = Math.floor(Math.random() * 1000000);
const subreddit = subreddits[Math.floor(Math.random() * subreddits.length)];
const hook = hooks[Math.floor(Math.random() * hooks.length)];
const music_url = musicUrls[Math.floor(Math.random() * musicUrls.length)];
return [{ json: { seed, subreddit, hook, music_url, timestamp: new Date().toISOString() } }];

const inputData = $input.all()[0].json;
const posts = (inputData.data && inputData.data.children) ? inputData.data.children : [];
const chaosData = $('Chaos Seed1').first().json;
const fallbackTopics = [
  "The psychological reason you can't fall asleep at night",
  "Why your brain replays embarrassing memories",
  "The hidden power of introversion",
  "Why smart people doubt themselves more",
  "The science of why music gives you chills",
  "How your childhood shapes your adult relationships",
  "The real meaning behind your recurring dreams"
];
const qualifying = posts.filter(p => p.data.ups >= 1000 && !p.data.stickied && !p.data.over_18 && p.data.title);
let topic;
if (qualifying.length > 0) {
  const top10 = qualifying.slice(0, 10);
  topic = top10[Math.floor(Math.random() * top10.length)].data.title;
} else {
  topic = fallbackTopics[Math.floor(Math.random() * fallbackTopics.length)];
}
return [{ json: { topic, hook: chaosData.hook, music_url: chaosData.music_url, seed: chaosData.seed } }];

let rawCritic = '';
try { rawCritic = $input.first().json.text || $input.first().json.output || ''; } catch(e) {}
const cleanedCritic = rawCritic.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
let script = '';
try { script = $('Script Writer1').first().json.text || $('Script Writer1').first().json.output || ''; } catch(e) {}
const cleanScript = script.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
let music_url = '';
try { music_url = $('Filter Viral Posts1').first().json.music_url || ''; } catch(e) {}
return [{ json: { script: cleanScript, music_url, critic_output: cleanedCritic, approved: true } }];

const visualMap = {
  brain: "neural network abstract", mind: "galaxy mind cosmic", glitch: "glitch art video",
  void: "black void abstract", hallway: "dark hallway endless", ocean: "deep ocean dark",
  space: "deep space stars nebula", abstract: "abstract geometric 3d", galaxy: "galaxy spiral stars",
  neon: "neon lights city", fire: "fire flames slow motion", water: "water droplet macro",
  smoke: "smoke dark background", static: "tv static noise", calm: "calm nature loop"
};
const fallbackScenes = [
  { index:1, sentence:"Your brain processes 11 million bits of information every second.", visual:"neural network abstract" },
  { index:2, sentence:"But you are only aware of about 40 bits.", visual:"black void abstract" },
  { index:3, sentence:"Your subconscious is running the show.", visual:"abstract geometric 3d" },
  { index:4, sentence:"And it has been doing this your entire life.", visual:"galaxy spiral stars" },
  { index:5, sentence:"Follow for more mind-bending facts.", visual:"neon lights city" }
];
let raw = '';
try { raw = $input.first().json.text || $input.first().json.output || ''; } catch(e) {}
let music_url = '';
try { music_url = $('Quality Gate1').first().json.music_url || ''; } catch(e) {}
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
raw = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) raw = jsonMatch[0];
let scenes;
try {
  const parsed = JSON.parse(raw);
  scenes = parsed.scenes || parsed;
  if (!Array.isArray(scenes)) throw new Error('not array');
  scenes = scenes.slice(0, 6).map((s, i) => {
    const k = (s.visual || '').toLowerCase().trim();
    return { index: s.index || (i+1), sentence: s.sentence || s.text || '', visual: visualMap[k] || s.visual || 'abstract geometric 3d' };
  }).filter(s => s.sentence.length > 0);
  if (scenes.length === 0) throw new Error('empty');
} catch(e) { scenes = fallbackScenes; }
return [{ json: { scenes, music_url } }];

const { scenes, music_url } = $input.first().json;
const base_folder = 'C:\\reddit vids n8n\\satisfying';
return scenes.map(scene => ({ json: {
  index: scene.index, sentence: scene.sentence, visual: scene.visual,
  base_folder, audio_filename: 'audio_' + scene.index + '.mp3',
  visual_filename: 'scene_' + scene.index + '_visual.mp4',
  music_url, total_scenes: scenes.length
}}));

const pexelsData = $input.first().json;
const sceneItem = $('Split Scenes1').item.json;
const { index, base_folder, visual_filename, audio_filename, sentence, music_url, total_scenes } = sceneItem;
const outputPath = base_folder + '\\' + visual_filename;
const videos = pexelsData.videos || [];
const hdVideos = videos.filter(v => (v.video_files||[]).some(f => f.quality === 'hd' && f.width >= 720));
const pool = hdVideos.length > 0 ? hdVideos : videos;
let downloadCommand;
if (pool.length > 0) {
  const picked = pool[Math.floor(Math.random() * pool.length)];
  const files = picked.video_files || [];
  const hdFile = files.find(f => f.quality === 'hd' && f.width >= 720) || files[0];
  const url = hdFile ? hdFile.link : '';
  downloadCommand = url
    ? `powershell -c "Invoke-WebRequest -Uri '${url}' -OutFile '${outputPath}' -Headers @{'User-Agent'='Mozilla/5.0'}"`
    : `ffmpeg -y -f lavfi -i "color=c=purple:s=720x1280:d=8" -c:v libx264 -pix_fmt yuv420p "${outputPath}"`;
} else {
  downloadCommand = `ffmpeg -y -f lavfi -i "color=c=purple:s=720x1280:d=8" -c:v libx264 -pix_fmt yuv420p "${outputPath}"`;
}
return [{ json: { downloadCommand, outputPath, index, base_folder, audio_filename, visual_filename, sentence, music_url, total_scenes } }];

const { base_folder, index, music_url, total_scenes } = $input.first().json;
const audioPath = base_folder + '\\audio_' + index + '.mp3';
const visualPath = base_folder + '\\scene_' + index + '_visual.mp4';
const outputPart = base_folder + '\\part_' + index + '.mp4';
const mergeCommand = `cd /d "${base_folder}" && ffmpeg -y -stream_loop -1 -i "${visualPath}" -i "${audioPath}" -map 0:v -map 1:a -vf "scale=720:1280:force_original_aspect_ratio=increase,crop=720:1280,setsar=1:1,eq=contrast=1.1:brightness=-0.05:saturation=0.9" -c:v libx264 -preset ultrafast -r 30 -c:a aac -shortest "${outputPart}"`;
return [{ json: { mergeCommand, music_url, total_scenes, base_folder } }];

